BEGIN;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '60s';
LOCK TABLE tenants,sections,categories,items,translations,published_snapshots IN SHARE ROW EXCLUSIVE MODE;
DO $rollout$
DECLARE before_state jsonb; after_state jsonb; inserted_count integer;
BEGIN
 SELECT evidence INTO before_state FROM (WITH t AS (
 SELECT id,slug,name,subtitle,address,hero_url,living_guide_hero_url,logo_url FROM tenants WHERE slug='meli-pu'
), s0 AS (SELECT s.* FROM sections s JOIN t ON t.id=s.tenant_id),
c0 AS (SELECT c.* FROM categories c JOIN s0 ON s0.id=c.section_id),
i0 AS (SELECT i.* FROM items i JOIN c0 ON c0.id=i.category_id),
s AS (SELECT * FROM s0 WHERE deleted_at IS NULL),
c AS (SELECT c0.* FROM c0 JOIN s ON s.id=c0.section_id WHERE c0.deleted_at IS NULL),
i AS (SELECT i0.* FROM i0 JOIN c ON c.id=i0.category_id WHERE i0.deleted_at IS NULL),
r AS (SELECT 'tenant' AS model,id FROM t UNION ALL SELECT 'section',id FROM s0 UNION ALL SELECT 'category',id FROM c0 UNION ALL SELECT 'item',id FROM i0),
tr AS (SELECT tr.* FROM translations tr JOIN r ON r.model=tr.model AND r.id=tr.record_id),
candidate AS (SELECT * FROM jsonb_to_recordset('[{"model":"item","record_id":"040e3521-dfc6-4f20-a6a9-fb3dfd1d5b14","field":"title","lang":"en","value":"Apartment 4"},{"model":"item","record_id":"040e3521-dfc6-4f20-a6a9-fb3dfd1d5b14","field":"title","lang":"de","value":"Apartment 4"},{"model":"item","record_id":"040e3521-dfc6-4f20-a6a9-fb3dfd1d5b14","field":"title","lang":"it","value":"Appartamento 4"},{"model":"item","record_id":"048efd21-d9ed-45ce-a017-cda9776fd651","field":"title","lang":"en","value":"Rental for 3-4 hours"},{"model":"item","record_id":"048efd21-d9ed-45ce-a017-cda9776fd651","field":"title","lang":"de","value":"Miete für 3-4 Stunden"},{"model":"item","record_id":"048efd21-d9ed-45ce-a017-cda9776fd651","field":"title","lang":"it","value":"Noleggio per 3-4 ore"},{"model":"item","record_id":"048efd21-d9ed-45ce-a017-cda9776fd651","field":"priceUnit","lang":"en","value":"3-4 hours"},{"model":"item","record_id":"048efd21-d9ed-45ce-a017-cda9776fd651","field":"priceUnit","lang":"de","value":"3-4 Stunden"},{"model":"item","record_id":"048efd21-d9ed-45ce-a017-cda9776fd651","field":"priceUnit","lang":"it","value":"3-4 ore"},{"model":"item","record_id":"048efd21-d9ed-45ce-a017-cda9776fd651","field":"body","lang":"en","value":"<p>The board comes folded in a handy bag, ready for action. A hand pump is included, so you can inflate it in just a few minutes anywhere, anytime.</p>"},{"model":"item","record_id":"048efd21-d9ed-45ce-a017-cda9776fd651","field":"body","lang":"de","value":"<p>Das Board wird zusammengefaltet in einer praktischen Tasche geliefert und ist bereit für den Einsatz. Eine Handpumpe ist im Lieferumfang enthalten, sodass Sie es überall und jederzeit in wenigen Minuten aufblasen können.</p>"},{"model":"item","record_id":"048efd21-d9ed-45ce-a017-cda9776fd651","field":"body","lang":"it","value":"<p>La tavola viene fornita ripiegata in una pratica borsa, pronta all''azione. È inclusa una pompa a mano, così potete gonfiarla in pochi minuti ovunque e in qualsiasi momento.</p>"},{"model":"item","record_id":"2d7920a4-6491-4b11-98c4-af6b3dff7227","field":"body","lang":"en","value":"<p>Turn on the TV using the remote control and the power button. For streaming content, select the HDMI 1 input.</p><p>If there is no picture, check that the correct source is selected on the remote control.</p>"},{"model":"item","record_id":"2d7920a4-6491-4b11-98c4-af6b3dff7227","field":"body","lang":"de","value":"<p>Schalten Sie den Fernseher mit der Fernbedienung und der Ein-/Aus-Taste ein. Wählen Sie für Streaming-Inhalte den Eingang HDMI 1.</p><p>Wenn kein Bild angezeigt wird, prüfen Sie, ob auf der Fernbedienung die richtige Quelle ausgewählt ist.</p>"},{"model":"item","record_id":"2d7920a4-6491-4b11-98c4-af6b3dff7227","field":"body","lang":"it","value":"<p>Accendete il televisore con il telecomando e il pulsante di accensione. Per i contenuti in streaming, selezionate l''ingresso HDMI 1.</p><p>Se non c''è immagine, controllate che sia selezionata la fonte corretta sul telecomando.</p>"},{"model":"item","record_id":"3d05a9a7-30c8-45b8-84c8-e77a415f5741","field":"body","lang":"en","value":"<p><strong>How to find us</strong></p><p>You can find us at Malija 143b in Izola. Since Google Maps sometimes takes you the wrong way, we have described the route ourselves — follow these instructions and you cannot go wrong.</p><p>From Koper, drive through the tunnel towards Izola and take the first exit for Izola. At the roundabout, take the second exit, then after approximately 50 metres, take the third exit at the next roundabout.</p><p>Continue straight for around 500 metres to the next roundabout and again take the third exit (towards Korte, Šared). You will pass Hofer on your right.</p><p>At the smaller roundabout, continue straight ahead (second exit). This is followed by an approximately 3 km ascent past the village of Šared.</p><p>Around 800 metres after Šared, there is a sign for Malija — turn right. After another 500 metres, there is a sign for Mala Seva on the right — turn there.</p><p>Drive for another approximately 800 metres through a small settlement. <strong>We are the last house on the right.</strong></p>"},{"model":"item","record_id":"3d05a9a7-30c8-45b8-84c8-e77a415f5741","field":"body","lang":"de","value":"<p><strong>So finden Sie uns</strong></p><p>Sie finden uns unter der Adresse Malija 143b in Izola. Da Google Maps Sie manchmal auf den falschen Weg führt, haben wir die Route selbst beschrieben — halten Sie sich an diese Anweisungen, dann können Sie uns nicht verfehlen.</p><p>Fahren Sie von Koper durch den Tunnel Richtung Izola und nehmen Sie die erste Ausfahrt nach Izola. Nehmen Sie im Kreisverkehr die zweite Ausfahrt und nach etwa 50 Metern im nächsten Kreisverkehr die dritte Ausfahrt.</p><p>Fahren Sie etwa 500 Meter geradeaus bis zum nächsten Kreisverkehr und nehmen Sie wieder die dritte Ausfahrt (Richtung Korte, Šared). Rechts fahren Sie an Hofer vorbei.</p><p>Fahren Sie am kleineren Kreisverkehr geradeaus weiter (zweite Ausfahrt). Es folgt ein etwa 3 km langer Anstieg vorbei am Dorf Šared.</p><p>Etwa 800 Meter nach Šared steht ein Schild nach Malija — biegen Sie rechts ab. Nach weiteren 500 Metern steht rechts ein Schild nach Mala Seva — biegen Sie dort ab.</p><p>Fahren Sie noch etwa 800 Meter durch eine kleine Siedlung. <strong>Wir sind das letzte Haus auf der rechten Seite.</strong></p>"},{"model":"item","record_id":"3d05a9a7-30c8-45b8-84c8-e77a415f5741","field":"body","lang":"it","value":"<p><strong>Come raggiungerci</strong></p><p>Ci trovate all''indirizzo Malija 143b a Izola. Poiché Google Maps a volte vi porta sulla strada sbagliata, abbiamo descritto noi stessi il percorso — seguite queste istruzioni e non potete sbagliare.</p><p>Da Koper attraversate il tunnel in direzione di Izola e prendete la prima uscita per Izola. Alla rotonda prendete la seconda uscita e, dopo circa 50 metri, alla rotonda successiva prendete la terza uscita.</p><p>Proseguite dritto per circa 500 metri fino alla rotonda successiva e prendete di nuovo la terza uscita (direzione Korte, Šared). Sulla destra passerete accanto a Hofer.</p><p>Alla rotonda più piccola proseguite dritto (seconda uscita). Segue una salita di circa 3 km passando per il villaggio di Šared.</p><p>Circa 800 metri dopo Šared c''è un cartello per Malija — svoltate a destra. Dopo altri 500 metri, sulla destra c''è un cartello per Mala Seva — svoltate lì.</p><p>Proseguite per altri circa 800 metri attraverso un piccolo insediamento. <strong>Siamo l''ultima casa sulla destra.</strong></p>"},{"model":"item","record_id":"41d78418-097d-4959-8ba5-19389f26627f","field":"body","lang":"en","value":"<p>Turn on the air conditioning using the remote control. The recommended temperature is 24 °C.</p><p>When leaving the apartment, please turn off the air conditioning and close the windows.</p>"},{"model":"item","record_id":"41d78418-097d-4959-8ba5-19389f26627f","field":"body","lang":"de","value":"<p>Schalten Sie die Klimaanlage mit der Fernbedienung ein. Die empfohlene Temperatur beträgt 24 °C.</p><p>Wenn Sie das Apartment verlassen, schalten Sie bitte die Klimaanlage aus und schließen Sie die Fenster.</p>"},{"model":"item","record_id":"41d78418-097d-4959-8ba5-19389f26627f","field":"body","lang":"it","value":"<p>Accendete l''aria condizionata con il telecomando. La temperatura consigliata è 24 °C.</p><p>Quando lasciate l''appartamento, spegnete per favore l''aria condizionata e chiudete le finestre.</p>"},{"model":"item","record_id":"4582653e-34e5-4381-a882-1125ada98d2d","field":"body","lang":"en","value":"<p>A selection of games for outdoor use and long afternoons in the shade is available for guests: rackets, cards, board games (including Človek, ne jezi se) and jigsaw puzzles.</p><p><strong>Where are the games?</strong></p><p>The games are stored to the right of the barbecue, in a box clearly marked „Igre“.</p>"},{"model":"item","record_id":"4582653e-34e5-4381-a882-1125ada98d2d","field":"body","lang":"de","value":"<p>Für Gäste steht eine Auswahl an Spielen für draußen und für lange Nachmittage im Schatten bereit: Schläger, Karten, Gesellschaftsspiele (auch Človek, ne jezi se) und Puzzles.</p><p><strong>Wo sind die Spiele?</strong></p><p>Die Spiele befinden sich rechts vom Grill in einer deutlich mit „Igre“ gekennzeichneten Kiste.</p>"},{"model":"item","record_id":"4582653e-34e5-4381-a882-1125ada98d2d","field":"body","lang":"it","value":"<p>Per gli ospiti è disponibile una selezione di giochi da esterno e per lunghi pomeriggi all''ombra: racchette, carte, giochi da tavolo (compreso Človek, ne jezi se) e puzzle.</p><p><strong>Dove sono i giochi?</strong></p><p>I giochi sono riposti a destra del barbecue, in una cassa chiaramente contrassegnata con „Igre“.</p>"},{"model":"item","record_id":"4860043d-3db3-4c26-bd6e-714ebfdbe8ce","field":"body","lang":"en","value":"<p>The board comes folded in a handy bag, ready for action. A hand pump is included, so you can inflate it in just a few minutes anywhere, anytime.</p>"},{"model":"item","record_id":"4860043d-3db3-4c26-bd6e-714ebfdbe8ce","field":"body","lang":"de","value":"<p>Das Board wird zusammengefaltet in einer praktischen Tasche geliefert und ist bereit für den Einsatz. Eine Handpumpe ist im Lieferumfang enthalten, sodass Sie es überall und jederzeit in wenigen Minuten aufblasen können.</p>"},{"model":"item","record_id":"4860043d-3db3-4c26-bd6e-714ebfdbe8ce","field":"body","lang":"it","value":"<p>La tavola viene fornita ripiegata in una pratica borsa, pronta all''azione. È inclusa una pompa a mano, così potete gonfiarla in pochi minuti ovunque e in qualsiasi momento.</p>"},{"model":"item","record_id":"4d89a336-336d-4c64-b832-c85160132a6c","field":"body","lang":"en","value":"<p>Please keep the boiler on throughout your stay. Please do not switch it off — otherwise you will be left without hot water.</p>"},{"model":"item","record_id":"4d89a336-336d-4c64-b832-c85160132a6c","field":"body","lang":"de","value":"<p>Bitte lassen Sie den Boiler während Ihres gesamten Aufenthalts eingeschaltet. Bitte schalten Sie ihn nicht aus — sonst haben Sie kein warmes Wasser.</p>"},{"model":"item","record_id":"4d89a336-336d-4c64-b832-c85160132a6c","field":"body","lang":"it","value":"<p>Lasciate il boiler acceso per tutta la durata del vostro soggiorno. Vi preghiamo di non spegnerlo — altrimenti rimarrete senza acqua calda.</p>"},{"model":"item","record_id":"6617360c-fdc5-455e-9e72-5269106f9a52","field":"body","lang":"en","value":"<p>A longer version with more swimming stops and enough time to enjoy the coastal towns as well.</p><p>Up to 4 people, each additional person +20 € (maximum 7). Boarding: Marina UP Izola.</p>"},{"model":"item","record_id":"6617360c-fdc5-455e-9e72-5269106f9a52","field":"body","lang":"de","value":"<p>Eine längere Variante mit mehr Badestopps und ausreichend Zeit, um auch die Küstenstädtchen zu genießen.</p><p>Bis zu 4 Personen, jede weitere Person +20 € (maximal 7). Einstieg: Marina UP Izola.</p>"},{"model":"item","record_id":"6617360c-fdc5-455e-9e72-5269106f9a52","field":"body","lang":"it","value":"<p>Una versione più lunga con più soste per il bagno e abbastanza tempo per godervi anche le cittadine costiere.</p><p>Fino a 4 persone, ogni persona aggiuntiva +20 € (massimo 7). Imbarco: Marina UP Izola.</p>"},{"model":"item","record_id":"6a4d3a34-8d54-49d4-bd68-8ea31f019edf","field":"body","lang":"en","value":"<p>Tell us what you would like, and the skipper will prepare a trip tailored to you.</p><p>Up to 4 people, each additional person +20 € (maximum 7).</p>"},{"model":"item","record_id":"6a4d3a34-8d54-49d4-bd68-8ea31f019edf","field":"body","lang":"de","value":"<p>Sagen Sie uns, was Sie sich wünschen, und der Skipper stellt eine Fahrt ganz nach Ihren Vorstellungen zusammen.</p><p>Bis zu 4 Personen, jede weitere Person +20 € (maximal 7).</p>"},{"model":"item","record_id":"6a4d3a34-8d54-49d4-bd68-8ea31f019edf","field":"body","lang":"it","value":"<p>Diteci cosa desiderate e lo skipper preparerà una navigazione su misura per voi.</p><p>Fino a 4 persone, ogni persona aggiuntiva +20 € (massimo 7).</p>"},{"model":"item","record_id":"7a885dec-33af-48d6-b883-d98a6a2a2ee0","field":"body","lang":"en","value":"<p><strong>Meli Pu Ice Cream</strong></p><p>Our ice cream vending machine in Marina Izola operates 24 hours a day, every day of the week. When you feel like it after dinner or after midnight — just drop by.</p>"},{"model":"item","record_id":"7a885dec-33af-48d6-b883-d98a6a2a2ee0","field":"body","lang":"de","value":"<p><strong>Meli Pu Ice Cream</strong></p><p>Unser Eisautomat in Marina Izola ist 24 Stunden am Tag, sieben Tage die Woche in Betrieb. Wenn Sie nach dem Abendessen oder nach Mitternacht Lust darauf haben — kommen Sie einfach vorbei.</p>"},{"model":"item","record_id":"7a885dec-33af-48d6-b883-d98a6a2a2ee0","field":"body","lang":"it","value":"<p><strong>Meli Pu Ice Cream</strong></p><p>Il nostro distributore automatico di gelati a Marina Izola è attivo 24 ore al giorno, tutti i giorni della settimana. Quando ne avete voglia dopo cena o dopo mezzanotte — passate pure.</p>"},{"model":"item","record_id":"91becb6d-b58c-43e9-8ef3-5b3fdd479084","field":"body","lang":"en","value":"<p>Network name: MeliPu</p><p>Password: MeliPu0301</p>"},{"model":"item","record_id":"91becb6d-b58c-43e9-8ef3-5b3fdd479084","field":"body","lang":"de","value":"<p>Netzwerkname: MeliPu</p><p>Passwort: MeliPu0301</p>"},{"model":"item","record_id":"91becb6d-b58c-43e9-8ef3-5b3fdd479084","field":"body","lang":"it","value":"<p>Nome della rete: MeliPu</p><p>Password: MeliPu0301</p>"},{"model":"item","record_id":"a1b3f0a4-4d72-4698-ae00-2c975cad3d09","field":"body","lang":"en","value":"<p>Experience the freedom of a private boat trip with your own skipper. Fun, relaxation and views of the Slovenian coast — just for your group.</p><p>Up to 4 people, each additional person +20 € (maximum 7). Boarding: Marina UP Izola; also possible in Koper, Piran, Portorož and Bernardin (+40 €).</p>"},{"model":"item","record_id":"a1b3f0a4-4d72-4698-ae00-2c975cad3d09","field":"body","lang":"de","value":"<p>Erleben Sie die Freiheit einer privaten Bootsfahrt mit Ihrem eigenen Skipper. Spaß, Entspannung und Ausblicke auf die slowenische Küste — nur für Ihre Gruppe.</p><p>Bis zu 4 Personen, jede weitere Person +20 € (maximal 7). Einstieg: Marina UP Izola; auch in Koper, Piran, Portorož und Bernardin möglich (+40 €).</p>"},{"model":"item","record_id":"a1b3f0a4-4d72-4698-ae00-2c975cad3d09","field":"body","lang":"it","value":"<p>Provate la libertà di una navigazione privata con il vostro skipper. Divertimento, relax e viste sulla costa slovena — solo per il vostro gruppo.</p><p>Fino a 4 persone, ogni persona aggiuntiva +20 € (massimo 7). Imbarco: Marina UP Izola; possibile anche a Koper, Piran, Portorož e Bernardin (+40 €).</p>"},{"model":"item","record_id":"b6416567-e2b4-4ece-8d38-43ec45c7820a","field":"body","lang":"en","value":"<p><strong>Lovely to have you here.</strong></p><p>We are delighted that you have chosen Meli Pu apartments for your getaway. Our house stands on a sunny slope above Izola, surrounded by olive trees and cypresses, with a view stretching all the way to the sea.</p><p>We wish you relaxed, warm and carefree days in our little piece of paradise. If you need anything, we are just a phone call away.</p>"},{"model":"item","record_id":"b6416567-e2b4-4ece-8d38-43ec45c7820a","field":"body","lang":"de","value":"<p><strong>Schön, dass Sie hier sind.</strong></p><p>Wir freuen uns, dass Sie für Ihre Auszeit die Apartments Meli Pu gewählt haben. Unser Haus steht an einem sonnigen Hang oberhalb von Izola, umgeben von Olivenbäumen und Zypressen, mit einem Blick, der bis zum Meer reicht.</p><p>Wir wünschen Ihnen entspannte, warme und unbeschwerte Tage in unserem kleinen Stück Paradies. Wenn Sie irgendetwas brauchen, sind wir nur einen Anruf entfernt.</p>"},{"model":"item","record_id":"b6416567-e2b4-4ece-8d38-43ec45c7820a","field":"body","lang":"it","value":"<p><strong>Che bello avervi qui.</strong></p><p>Siamo lieti che abbiate scelto gli appartamenti Meli Pu per la vostra vacanza. La nostra casa sorge su un soleggiato pendio sopra Izola, circondata da ulivi e cipressi, con una vista che arriva fino al mare.</p><p>Vi auguriamo giornate rilassanti, calde e spensierate nel nostro piccolo angolo di paradiso. Se avete bisogno di qualsiasi cosa, siamo a una telefonata di distanza.</p>"},{"model":"item","record_id":"d06aa2f4-ae23-4bd4-8beb-adc590c681a2","field":"body","lang":"en","value":"<p>Extra virgin olive oil from our olives — picked on the slopes above Izola and pressed on the same day. An excellent souvenir and an even better dinner.</p>"},{"model":"item","record_id":"d06aa2f4-ae23-4bd4-8beb-adc590c681a2","field":"body","lang":"de","value":"<p>Natives Olivenöl extra aus unseren Oliven — an den Hängen oberhalb von Izola geerntet und noch am selben Tag gepresst. Ein ausgezeichnetes Souvenir und ein noch besseres Abendessen.</p>"},{"model":"item","record_id":"d06aa2f4-ae23-4bd4-8beb-adc590c681a2","field":"body","lang":"it","value":"<p>Olio extravergine d''oliva dalle nostre olive — raccolte sui pendii sopra Izola e spremute nello stesso giorno. Un ottimo souvenir e una cena ancora migliore.</p>"},{"model":"item","record_id":"d16868d6-d2c1-4485-9380-b9ebe3c04b40","field":"body","lang":"en","value":"<p>Rent a scooter and explore at your own pace — fast, fun, and perfect for a holiday adventure. Two helmets are included.</p><p><strong>Fuel:</strong> you pick up the vehicle with a full tank and return it that way; otherwise, fuel will be charged.</p>"},{"model":"item","record_id":"d16868d6-d2c1-4485-9380-b9ebe3c04b40","field":"body","lang":"de","value":"<p>Mieten Sie einen Motorroller und erkunden Sie die Umgebung auf eigene Faust — schnell, unterhaltsam und perfekt für ein Urlaubsabenteuer. Zwei Helme sind inklusive.</p><p><strong>Kraftstoff:</strong> Sie übernehmen das Fahrzeug mit vollem Tank und geben es auch so zurück, andernfalls wird der Kraftstoff berechnet.</p>"},{"model":"item","record_id":"d16868d6-d2c1-4485-9380-b9ebe3c04b40","field":"body","lang":"it","value":"<p>Noleggiate uno scooter ed esplorate in autonomia — veloce, divertente e perfetto per un''avventura in vacanza. Sono inclusi due caschi.</p><p><strong>Carburante:</strong> ritirate il veicolo con il serbatoio pieno e riconsegnatelo allo stesso modo, altrimenti il carburante verrà addebitato.</p>"},{"model":"item","record_id":"e25e02e5-bd2d-4191-aa79-2107bdce4bd3","field":"body","lang":"en","value":"<p>The barbecue area is made for relaxed evenings and socialising. The built-in barbecue station and worktop allow you to cook outdoors, right next to the apartments.</p><p><strong>Instructions for use</strong></p><p>Before use, open the valve on the gas cylinder.</p><p>After use, be sure to turn off the gas and clean the barbecue.</p>"},{"model":"item","record_id":"e25e02e5-bd2d-4191-aa79-2107bdce4bd3","field":"body","lang":"de","value":"<p>Der Grillbereich ist wie geschaffen für entspannte Abende und geselliges Beisammensein. Die eingebaute Grillstation und die Arbeitsplatte ermöglichen das Kochen im Freien, direkt neben den Apartments.</p><p><strong>Gebrauchsanweisung</strong></p><p>Öffnen Sie vor der Benutzung das Ventil an der Gasflasche.</p><p>Schließen Sie nach der Benutzung unbedingt das Gas und reinigen Sie den Grill.</p>"},{"model":"item","record_id":"e25e02e5-bd2d-4191-aa79-2107bdce4bd3","field":"body","lang":"it","value":"<p>L''area barbecue è perfetta per serate rilassate e momenti di convivialità. La postazione barbecue integrata e il piano di lavoro consentono di cucinare all''aperto, proprio accanto agli appartamenti.</p><p><strong>Istruzioni per l''uso</strong></p><p>Prima dell''uso, aprite la valvola della bombola del gas.</p><p>Dopo l''uso, chiudete sempre il gas e pulite il barbecue.</p>"},{"model":"item","record_id":"e8d1c420-1234-4959-87f4-5d7508ff54ce","field":"body","lang":"en","value":"<p>Parking is free for our guests and is provided in the courtyard next to the house.</p><p>Please note that the owner accepts no responsibility for vehicles, any damage to them, or items left in the vehicle.</p><p><strong>Electric vehicle charging station</strong></p><p>An electric vehicle charging station is also available. Please contact the host first to use it.</p>"},{"model":"item","record_id":"e8d1c420-1234-4959-87f4-5d7508ff54ce","field":"body","lang":"de","value":"<p>Das Parken ist für unsere Gäste kostenlos und im Hof neben dem Haus möglich.</p><p>Bitte beachten Sie, dass der Eigentümer keine Verantwortung für Fahrzeuge, mögliche Schäden daran oder im Fahrzeug zurückgelassene Gegenstände übernimmt.</p><p><strong>Ladestation für Elektrofahrzeuge</strong></p><p>Eine Ladestation für Elektrofahrzeuge steht ebenfalls zur Verfügung. Bitte wenden Sie sich vor der Nutzung zunächst an den Gastgeber.</p>"},{"model":"item","record_id":"e8d1c420-1234-4959-87f4-5d7508ff54ce","field":"body","lang":"it","value":"<p>Il parcheggio è gratuito per i nostri ospiti ed è disponibile nel cortile accanto alla casa.</p><p>Vi preghiamo di notare che il proprietario non si assume alcuna responsabilità per i veicoli, eventuali danni agli stessi o oggetti lasciati nel veicolo.</p><p><strong>Stazione di ricarica per veicoli elettrici</strong></p><p>È disponibile anche una stazione di ricarica per veicoli elettrici. Per utilizzarla, contattate prima il gestore.</p>"},{"model":"item","record_id":"f2923fa6-1a82-445c-9dfb-bf4dbd504f8c","field":"title","lang":"en","value":"Apartment 3"},{"model":"item","record_id":"f2923fa6-1a82-445c-9dfb-bf4dbd504f8c","field":"title","lang":"de","value":"Apartment 3"},{"model":"item","record_id":"f2923fa6-1a82-445c-9dfb-bf4dbd504f8c","field":"title","lang":"it","value":"Appartamento 3"},{"model":"item","record_id":"f61527a3-503e-4b3d-91bc-1161d4e96312","field":"body","lang":"en","value":"<p>Press the <strong>left button</strong> on the remote control — the light will turn on and the gate will start opening.</p><p>The gate remains open for 2 minutes, then closes automatically.</p><p>Please do not stop too close to the fence: there is a sensor there, and the gate will not open in that case.</p>"},{"model":"item","record_id":"f61527a3-503e-4b3d-91bc-1161d4e96312","field":"body","lang":"de","value":"<p>Drücken Sie die <strong>linke Taste</strong> auf der Fernbedienung — die Kontrollleuchte leuchtet auf und das Tor beginnt sich zu öffnen.</p><p>Das Tor bleibt 2 Minuten geöffnet und schließt sich dann automatisch.</p><p>Bitte halten Sie nicht zu nah am Zaun an: Dort befindet sich ein Sensor, und das Tor wird sich in diesem Fall nicht öffnen.</p>"},{"model":"item","record_id":"f61527a3-503e-4b3d-91bc-1161d4e96312","field":"body","lang":"it","value":"<p>Premete il <strong>pulsante sinistro</strong> sul telecomando — la spia si accenderà e il cancello inizierà ad aprirsi.</p><p>Il cancello rimane aperto per 2 minuti, poi si chiude automaticamente.</p><p>Vi preghiamo di non fermarvi troppo vicino alla recinzione: lì c''è un sensore e, in questo caso, il cancello non si aprirà.</p>"},{"model":"item","record_id":"f85f6f77-c57e-4f87-86b2-d11f8673dad2","field":"body","lang":"en","value":"<p><strong>Check-in from 14:00</strong></p><p>At check-in, the host requires your identity document. Only registered guests may stay in the apartment.</p><p>Please inform the host in advance of any possible visitors.</p><p>At check-in, we will inspect the equipment and inventory together with the host according to the list.</p>"},{"model":"item","record_id":"f85f6f77-c57e-4f87-86b2-d11f8673dad2","field":"body","lang":"de","value":"<p><strong>Check-in ab 14:00</strong></p><p>Beim Check-in benötigt der Gastgeber Ihren Ausweis. Im Apartment dürfen nur angemeldete Gäste übernachten.</p><p>Bitte informieren Sie den Gastgeber im Voraus über mögliche Besucher.</p><p>Beim Check-in überprüfen wir gemeinsam mit dem Gastgeber die Ausstattung und das Inventar anhand der Liste.</p>"},{"model":"item","record_id":"f85f6f77-c57e-4f87-86b2-d11f8673dad2","field":"body","lang":"it","value":"<p><strong>Check-in dalle 14:00</strong></p><p>Al check-in, il gestore richiede il vostro documento d''identità. Nell''appartamento possono soggiornare solo gli ospiti registrati.</p><p>Vi preghiamo di informare anticipatamente il gestore di eventuali visite.</p><p>Al check-in, insieme al gestore controlliamo l''attrezzatura e l''inventario secondo l''elenco.</p>"},{"model":"item","record_id":"fd46cfef-1de9-4bbf-b2d3-b66f2ccad996","field":"body","lang":"en","value":"<p>The outdoor fitness area right next to the apartments is a simple way to stay active in the fresh air — with a punching bag, bar, bench and weights.</p><p>In the box next to the fitness area, you will find weights, mats and small equipment. Please put them back after use.</p>"},{"model":"item","record_id":"fd46cfef-1de9-4bbf-b2d3-b66f2ccad996","field":"body","lang":"de","value":"<p>Der Outdoor-Fitnessbereich direkt neben den Apartments ist eine einfache Möglichkeit, an der frischen Luft aktiv zu bleiben — mit einem Boxsack, einer Stange, einer Bank und Gewichten.</p><p>In der Box neben dem Fitnessbereich finden Sie Gewichte, Matten und Kleingeräte. Bitte räumen Sie diese nach der Benutzung wieder zurück.</p>"},{"model":"item","record_id":"fd46cfef-1de9-4bbf-b2d3-b66f2ccad996","field":"body","lang":"it","value":"<p>L''area fitness all''aperto proprio accanto agli appartamenti è un modo semplice per mantenervi attivi all''aria aperta — con un sacco da boxe, una sbarra, una panca e pesi.</p><p>Nella cassa accanto all''area fitness troverete pesi, tappetini e piccole attrezzature. Vi preghiamo di riporli dopo l''uso.</p>"}]'::jsonb) AS x(model text,record_id uuid,field text,lang text,value text)),
protected AS (SELECT tr.* FROM tr WHERE NOT EXISTS(SELECT 1 FROM candidate x WHERE (x.model,x.record_id,x.field,x.lang)=(tr.model,tr.record_id,tr.field,tr.lang)))
SELECT jsonb_build_object(
'source',md5(jsonb_build_object('tenants',(SELECT jsonb_agg(t ORDER BY id) FROM t),'sections',(SELECT jsonb_agg(s ORDER BY id) FROM s),'categories',(SELECT jsonb_agg(c ORDER BY id) FROM c),'items',(SELECT jsonb_agg(i ORDER BY id) FROM i))::text),
'translations',md5(COALESCE((SELECT jsonb_agg(protected ORDER BY id) FROM protected),'[]'::jsonb)::text),
'snapshots',md5(COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.tenant_id) FROM published_snapshots p JOIN t ON t.id=p.tenant_id),'[]'::jsonb)::text)
) AS evidence) q;
 IF before_state IS DISTINCT FROM '{"source":"f720aac9c9afc8caf977936e233c9241","snapshots":"3e43a8734677de29bb724d4f96d21d18","translations":"53774d5d1c0faf8b0b9d34e0039d5d7f"}'::jsonb THEN
